import{G as e,W as t,n,rt as r}from"./chunks/framework.DBm3e_pg.js";var i=JSON.parse(`{"title":"DMZ Gateway Lab Environment for XDP, WAF and Reverse Proxy Testing","description":"","frontmatter":{},"headers":[],"relativePath":"vi/edge/edge.md","filePath":"vi/edge/edge.md"}`),a={name:`vi/edge/edge.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="dmz-gateway-lab-environment-for-xdp-waf-and-reverse-proxy-testing" tabindex="-1">DMZ Gateway Lab Environment for XDP, WAF and Reverse Proxy Testing <a class="header-anchor" href="#dmz-gateway-lab-environment-for-xdp-waf-and-reverse-proxy-testing" aria-label="Permalink to “DMZ Gateway Lab Environment for XDP, WAF and Reverse Proxy Testing”">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>Tài liệu này mô tả môi trường lab dùng để phát triển và kiểm thử các thành phần bảo mật và xử lý lưu lượng mạng ở Layer 3–7, bao gồm:</p><ul><li>XDP/eBPF</li><li>Web Application Firewall (WAF)</li><li>Reverse Proxy</li><li>Rate Limiting</li><li>DDoS Mitigation</li></ul><p>Mục tiêu là mô phỏng kiến trúc triển khai thực tế (production) trong đó Gateway được đặt trong vùng DMZ (Demilitarized Zone) và hoạt động như điểm tiếp nhận lưu lượng từ Internet trước khi chuyển tiếp tới Origin Server.</p><p>Toàn bộ môi trường được xây dựng bằng Linux Network Namespace nhằm tạo ra các network stack độc lập trên cùng một máy chủ, cho phép kiểm thử các luồng mạng thực tế mà không cần sử dụng máy ảo hoặc hạ tầng vật lý riêng biệt.</p><hr><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “Architecture”">​</a></h2><p>Môi trường bao gồm ba thành phần chính:</p><h3 id="client-namespace" tabindex="-1">Client Namespace <a class="header-anchor" href="#client-namespace" aria-label="Permalink to “Client Namespace”">​</a></h3><p>Mô phỏng người dùng hoặc hệ thống bên ngoài Internet.</p><p>Client gửi request tới Gateway thông qua interface public của DMZ.</p><h3 id="gateway-namespace-dmz" tabindex="-1">Gateway Namespace (DMZ) <a class="header-anchor" href="#gateway-namespace-dmz" aria-label="Permalink to “Gateway Namespace (DMZ)”">​</a></h3><p>Mô phỏng Reverse Proxy hoặc Edge Gateway trong môi trường production.</p><p>Gateway chịu trách nhiệm:</p><ul><li>Nhận lưu lượng từ Internet</li><li>Thực thi XDP/eBPF</li><li>Thực thi WAF</li><li>Áp dụng Rate Limiting hoặc DDoS Protection</li><li>Forward request tới Origin Server</li></ul><p>Interface <code>veth0</code> đóng vai trò là public-facing network interface và là nơi chương trình XDP được attach.</p><h3 id="host-network" tabindex="-1">Host Network <a class="header-anchor" href="#host-network" aria-label="Permalink to “Host Network”">​</a></h3><p>Đóng vai trò uplink router cho Gateway.</p><p>Host thực hiện:</p><ul><li>IP Forwarding</li><li>NAT</li><li>Kết nối Gateway tới Internet thực</li></ul><p>Origin Server không nằm trong môi trường lab mà là các website hoặc API thực trên Internet.</p><p>Ví dụ:</p><ul><li><a href="https://google.com" target="_blank" rel="noreferrer">https://google.com</a></li><li><a href="https://github.com" target="_blank" rel="noreferrer">https://github.com</a></li><li><a href="https://httpbin.org" target="_blank" rel="noreferrer">https://httpbin.org</a></li><li>Hệ thống backend thực tế của doanh nghiệp</li></ul><hr><h2 id="network-topology" tabindex="-1">Network Topology <a class="header-anchor" href="#network-topology" aria-label="Permalink to “Network Topology”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>                              Internet</span></span>
<span class="line"><span>                                  │</span></span>
<span class="line"><span>                                  ▼</span></span>
<span class="line"><span>                           Origin Server</span></span>
<span class="line"><span>                                  ▲</span></span>
<span class="line"><span>                                  │</span></span>
<span class="line"><span>                       NAT / Forwarding</span></span>
<span class="line"><span>                                  │</span></span>
<span class="line"><span>                                  ▼</span></span>
<span class="line"><span>+------------------------------------------------------+</span></span>
<span class="line"><span>|                    Host Linux                        |</span></span>
<span class="line"><span>|                                                      |</span></span>
<span class="line"><span>|   host-uplink (192.168.100.1/24)                     |</span></span>
<span class="line"><span>+-------------------------▲----------------------------+</span></span>
<span class="line"><span>                          │</span></span>
<span class="line"><span>                          │</span></span>
<span class="line"><span>                          ▼</span></span>
<span class="line"><span>+------------------------------------------------------+</span></span>
<span class="line"><span>|                 gateway-ns (DMZ)                     |</span></span>
<span class="line"><span>|                                                      |</span></span>
<span class="line"><span>|  veth0      : 203.0.113.1/24                         |</span></span>
<span class="line"><span>|  dmz-uplink : 192.168.100.2/24                       |</span></span>
<span class="line"><span>|                                                      |</span></span>
<span class="line"><span>|  Components:                                         |</span></span>
<span class="line"><span>|    - XDP/eBPF                                        |</span></span>
<span class="line"><span>|    - WAF                                             |</span></span>
<span class="line"><span>|    - Reverse Proxy                                   |</span></span>
<span class="line"><span>+-------------------------▲----------------------------+</span></span>
<span class="line"><span>                          │</span></span>
<span class="line"><span>                          │</span></span>
<span class="line"><span>                          ▼</span></span>
<span class="line"><span>+------------------------------------------------------+</span></span>
<span class="line"><span>|                    client-ns                         |</span></span>
<span class="line"><span>|                                                      |</span></span>
<span class="line"><span>|   veth-client : 203.0.113.2/24                       |</span></span>
<span class="line"><span>+------------------------------------------------------+</span></span></code></pre></div><hr><h2 id="packet-flow" tabindex="-1">Packet Flow <a class="header-anchor" href="#packet-flow" aria-label="Permalink to “Packet Flow”">​</a></h2><p>Một request từ client sẽ đi qua các thành phần theo thứ tự:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Client</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>veth-client</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>veth0</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>XDP</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>WAF</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>Reverse Proxy</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>dmz-uplink</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>Host NAT</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>Internet</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>Origin Server</span></span></code></pre></div><p>Trong quá trình xử lý, chương trình XDP được attach trên <code>veth0</code> sẽ nhìn thấy toàn bộ lưu lượng đi vào Gateway trước khi packet được chuyển lên Linux Networking Stack.</p><p>Ví dụ:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Source IP      = 203.0.113.2</span></span>
<span class="line"><span>Destination IP = 203.0.113.1</span></span></code></pre></div><p>Điều này cho phép kiểm thử chính xác các cơ chế:</p><ul><li>IP Filtering</li><li>Geo Blocking</li><li>SYN Flood Protection</li><li>Rate Limiting</li><li>DDoS Mitigation</li><li>Early Packet Drop bằng XDP</li></ul><hr><h2 id="why-this-architecture" tabindex="-1">Why This Architecture <a class="header-anchor" href="#why-this-architecture" aria-label="Permalink to “Why This Architecture”">​</a></h2><p>Mô hình này được lựa chọn vì mang lại nhiều đặc điểm tương đồng với môi trường production:</p><ul><li>Gateway được cô lập hoàn toàn khỏi host.</li><li>Có public-facing interface riêng (<code>veth0</code>).</li><li>Hỗ trợ attach XDP ở vị trí tương đương NIC public.</li><li>Có đường outbound thực ra Internet.</li><li>Không cần backend giả lập.</li><li>Có thể kiểm thử đầy đủ luồng Client → Gateway → Origin.</li><li>Có thể mở rộng thêm nhiều client namespace để mô phỏng lưu lượng lớn hoặc tấn công DDoS.</li></ul><p>Kiến trúc này phù hợp cho việc phát triển và kiểm thử các hệ thống Edge Proxy, WAF, API Gateway hoặc DDoS Protection trước khi triển khai lên môi trường thực tế.</p>`,41)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};